     1→<script lang="ts">
     2→	import 'pdfjs-dist/web/pdf_viewer.css';
     3→	import type { getDocument, TextItem } from 'pdfjs-dist/types/src/display/api';
     4→	import type { GlobalWorkerOptions, TextLayer } from 'pdfjs-dist';
     5→	import type { PageData } from './$types';
     6→
     7→	let { data }: { data: PageData } = $props();
     8→
     9→	let pdfjs: {
    10→		getDocument: typeof getDocument;
    11→		GlobalWorkerOptions: typeof GlobalWorkerOptions;
    12→		TextLayer: typeof TextLayer;
    13→	} | null = null;
    14→
    15→	async function loadPdfJs() {
    16→		if (!pdfjs) {
    17→			const { getDocument, GlobalWorkerOptions, TextLayer } = await import('pdfjs-dist');
    18→			const worker = await import('pdfjs-dist/build/pdf.worker.mjs?url');
    19→			GlobalWorkerOptions.workerSrc = worker.default;
    20→			pdfjs = { getDocument, GlobalWorkerOptions, TextLayer };
    21→		}
    22→		return pdfjs;
    23→	}
    24→
    25→	let pdfFile = $state<File | null>(null);
    26→	let pdfUrl = $state<string | null>(null);
    27→
    28→	// Store page data for search
    29→	interface PageTextData {
    30→		pageWrapper: HTMLElement;
    31→		viewport: { width: number; height: number; scale: number };
    32→		textItems: Array<{
    33→			str: string;
    34→			transform: number[];
    35→			width: number;
    36→			height: number;
    37→		}>;
    38→	}
    39→	let pagesData: PageTextData[] = [];
    40→
    41→	// Search state
    42→	let searchQuery = $state<string>('');
    43→	let matchCount = $state<number>(0);
    44→	let currentMatchIndex = $state<number>(0);
    45→	let highlightElements: HTMLElement[] = [];
    46→	let searchInputEl = $state<HTMLInputElement | null>(null);
    47→	let matchCase = $state<boolean>(false);
    48→	let matchWholeWord = $state<boolean>(false);
    49→	let showSearchPopup = $state<boolean>(false);
    50→
    51→	function performSearch() {
    52→		// Clear previous highlights
    53→		document.querySelectorAll('.search-highlight-overlay').forEach((el) => el.remove());
    54→		highlightElements = [];
    55→		matchCount = 0;
    56→		currentMatchIndex = 0;
    57→
    58→		if (!searchQuery.trim() || pagesData.length === 0) return;
    59→
    60→		const query = matchCase ? searchQuery : searchQuery.toLowerCase();
    61→
    62→		// Search through each page's text data
    63→		pagesData.forEach((pageData) => {
    64→			// Build combined text with character position mapping
    65→			interface CharInfo {
    66→				itemIndex: number;
    67→				charIndex: number;
    68→			}
    69→			const charMap: CharInfo[] = [];
    70→			let combinedText = '';
    71→
    72→			pageData.textItems.forEach((item, itemIndex) => {
    73→				for (let i = 0; i < item.str.length; i++) {
    74→					charMap.push({ itemIndex, charIndex: i });
    75→				}
    76→				combinedText += item.str;
    77→			});
    78→
    79→			// Find matches
    80→			const textToSearch = matchCase ? combinedText : combinedText.toLowerCase();
    81→			let searchPos = 0;
    82→
    83→			while (true) {
    84→				const matchIndex = textToSearch.indexOf(query, searchPos);
    85→				if (matchIndex === -1) break;
    86→
    87→				// Check whole word boundary if enabled
    88→				if (matchWholeWord) {
    89→					const charBefore = matchIndex > 0 ? textToSearch[matchIndex - 1] : ' ';
    90→					const charAfter =
    91→						matchIndex + query.length < textToSearch.length
    92→							? textToSearch[matchIndex + query.length]
    93→							: ' ';
    94→					const isWordBoundaryBefore = !/\w/.test(charBefore);
    95→					const isWordBoundaryAfter = !/\w/.test(charAfter);
    96→
    97→					if (!isWordBoundaryBefore || !isWordBoundaryAfter) {
    98→						searchPos = matchIndex + 1;
    99→						continue;
   100→					}
   101→				}
   102→
   103→				const matchEnd = matchIndex + query.length;
   104→				matchCount++;
   105→
   106→				// Find which text items this match spans
   107→				const startChar = charMap[matchIndex];
   108→				const endChar = charMap[matchEnd - 1];
   109→
   110→				if (!startChar || !endChar) {
   111→					searchPos = matchIndex + 1;
   112→					continue;
   113→				}
   114→
   115→				// Create highlights for each text item in this match
   116→				for (let itemIdx = startChar.itemIndex; itemIdx <= endChar.itemIndex; itemIdx++) {
   117→					const item = pageData.textItems[itemIdx];
   118→					const transform = item.transform;
   119→
   120→					// Transform matrix: [scaleX, skewY, skewX, scaleY, translateX, translateY]
   121→					const x = transform[4];
   122→					const y = transform[5];
   123→					const fontHeight = Math.abs(transform[3]); // scaleY = font height in PDF units
   124→
   125→					// Calculate the portion of this item that's highlighted
   126→					let highlightStartChar = 0;
   127→					let highlightEndChar = item.str.length;
   128→
   129→					if (itemIdx === startChar.itemIndex) {
   130→						highlightStartChar = startChar.charIndex;
   131→					}
   132→					if (itemIdx === endChar.itemIndex) {
   133→						highlightEndChar = endChar.charIndex + 1;
   134→					}
   135→
   136→					// item.width is already the total width in PDF units
   137→					const charWidth = item.width / item.str.length;
   138→					const highlightX = x + highlightStartChar * charWidth;
   139→					const highlightWidth = (highlightEndChar - highlightStartChar) * charWidth;
   140→
   141→					// Create highlight overlay
   142→					const highlight = document.createElement('div');
   143→					highlight.className = 'search-highlight-overlay';
   144→					highlight.dataset.matchIndex = String(matchCount - 1);
   145→
   146→					// Position in PDF coordinates, then scale to viewport
   147→					const scale = pageData.viewport.scale;
   148→					highlight.style.left = `${highlightX * scale}px`;
   149→					highlight.style.bottom = `${y * scale}px`;
   150→					highlight.style.width = `${Math.max(highlightWidth * scale, 4)}px`;
   151→					highlight.style.height = `${fontHeight * scale}px`;
   152→
   153→					pageData.pageWrapper.appendChild(highlight);
   154→					highlightElements.push(highlight);
   155→				}
   156→
   157→				searchPos = matchIndex + 1;
   158→			}
   159→		});
   160→
   161→		if (highlightElements.length > 0) {
   162→			scrollToMatch(0);
   163→		}
   164→	}
   165→
   166→	function scrollToMatch(index: number) {
   167→		// Remove current highlight styling
   168→		highlightElements.forEach((el) => el.classList.remove('current-match'));
   169→
   170→		if (matchCount === 0) return;
   171→
   172→		currentMatchIndex = ((index % matchCount) + matchCount) % matchCount;
   173→
   174→		// Find all highlights for this match and mark them as current
   175→		const currentHighlights = highlightElements.filter(
   176→			(el) => el.dataset.matchIndex === String(currentMatchIndex)
   177→		);
   178→
   179→		currentHighlights.forEach((el) => el.classList.add('current-match'));
   180→
   181→		if (currentHighlights.length > 0) {
   182→			currentHighlights[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
   183→		}
   184→	}
   185→
   186→	function nextMatch() {
   187→		scrollToMatch(currentMatchIndex + 1);
   188→	}
   189→
   190→	function prevMatch() {
   191→		scrollToMatch(currentMatchIndex - 1);
   192→	}
   193→
   194→	function handleSearchKeydown(event: KeyboardEvent) {
   195→		if (event.key === 'Escape') {
   196→			searchQuery = '';
   197→			performSearch();
   198→			showSearchPopup = false;
   199→		}
   200→	}
   201→
   202→	function openSearch() {
   203→		showSearchPopup = true;
   204→		// Focus after DOM update
   205→		setTimeout(() => {
   206→			searchInputEl?.focus();
   207→			searchInputEl?.select();
   208→		}, 0);
   209→	}
   210→
   211→	function closeSearch() {
   212→		searchQuery = '';
   213→		performSearch();
   214→		showSearchPopup = false;
   215→	}
   216→
   217→	function toggleMatchCase() {
   218→		matchCase = !matchCase;
   219→		performSearch();
   220→	}
   221→
   222→	function toggleMatchWholeWord() {
   223→		matchWholeWord = !matchWholeWord;
   224→		performSearch();
   225→	}
   226→
   227→	$effect(() => {
   228→		const hasPdf = Boolean(pdfUrl);
   229→		function onKeydown(e: KeyboardEvent) {
   230→			// Cmd+f: Open search popup (always prevent browser's native find dialog)
   231→			if ((e.metaKey || e.ctrlKey) && e.key === 'f') {
   232→				e.preventDefault();
   233→				if (hasPdf) {
   234→					openSearch();
   235→				}
   236→			}
   237→			// Cmd+g: Next match
   238→			if ((e.metaKey || e.ctrlKey) && e.key === 'g' && !e.shiftKey && !e.altKey) {
   239→				if (hasPdf && matchCount > 0) {
   240→					e.preventDefault();
   241→					nextMatch();
   242→				}
   243→			}
   244→			// Cmd+Shift+g: Previous match
   245→			if ((e.metaKey || e.ctrlKey) && e.key === 'g' && e.shiftKey && !e.altKey) {
   246→				if (hasPdf && matchCount > 0) {
   247→					e.preventDefault();
   248→					prevMatch();
   249→				}
   250→			}
   251→			// Cmd+Opt+c: Toggle match case
   252→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyC') {
   253→				if (hasPdf) {
   254→					e.preventDefault();
   255→					toggleMatchCase();
   256→				}
   257→			}
   258→			// Cmd+Opt+w: Toggle match whole word
   259→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyW') {
   260→				if (hasPdf) {
   261→					e.preventDefault();
   262→					toggleMatchWholeWord();
   263→				}
   264→			}
   265→		}
   266→		document.addEventListener('keydown', onKeydown, true);
   267→		return () => document.removeEventListener('keydown', onKeydown, true);
   268→	});
   269→
   270→	async function handleFileChange(event: Event) {
   271→		if (!(event.target instanceof HTMLInputElement)) return;
   272→		const pdfjs = await loadPdfJs();
   273→		const input = event.target;
   274→
   275→		const container = document.getElementById('pdf-container');
   276→
   277→		if (input.files && input.files[0] && container) {
   278→			pdfFile = input.files[0];
   279→			pdfUrl = URL.createObjectURL(pdfFile);
   280→			container.innerHTML = '';
   281→			pagesData = [];
   282→			searchQuery = '';
   283→			matchCount = 0;
   284→
   285→			const fileReader = new FileReader();
   286→
   287→			fileReader.onload = async (e) => {
   288→				if (!e.target || !(e.target.result instanceof ArrayBuffer)) return;
   289→				const pdf = await pdfjs.getDocument({ data: new Uint8Array(e.target.result) }).promise;
   290→
   291→				for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
   292→					const page = await pdf.getPage(pageNum);
   293→					const viewport = page.getViewport({ scale: 1.5 });
   294→
   295→					// Create page wrapper
   296→					const pageWrapper = document.createElement('div');
   297→					pageWrapper.className = 'page-wrapper';
   298→					pageWrapper.style.width = `${viewport.width}px`;
   299→					pageWrapper.style.height = `${viewport.height}px`;
   300→
   301→					// Create and render canvas
   302→					const canvas = document.createElement('canvas');
   303→					const context = canvas.getContext('2d');
   304→
   305→					if (!context) return;
   306→
   307→					canvas.height = viewport.height;
   308→					canvas.width = viewport.width;
   309→
   310→					await page.render({ canvasContext: context, viewport }).promise;
   311→					pageWrapper.appendChild(canvas);
   312→
   313→					// Create and render text layer
   314→					const textLayerDiv = document.createElement('div');
   315→					textLayerDiv.className = 'textLayer';
   316→					const PDF_TO_CSS_UNITS = 96 / 72;
   317→					textLayerDiv.style.setProperty(
   318→						'--scale-factor',
   319→						(viewport.scale * PDF_TO_CSS_UNITS).toString()
   320→					);
   321→
   322→					const textContent = await page.getTextContent();
   323→
   324→					// Store text data for search
   325→					const textItems = textContent.items
   326→						.filter((item): item is TextItem => 'str' in item && item.str.length > 0)
   327→						.map((item) => ({
   328→							str: item.str,
   329→							transform: item.transform,
   330→							width: item.width,
   331→							height: item.height
   332→						}));
   333→
   334→					pagesData.push({
   335→						pageWrapper,
   336→						viewport: { width: viewport.width, height: viewport.height, scale: viewport.scale },
   337→						textItems
   338→					});
   339→
   340→					const textLayer = new pdfjs.TextLayer({
   341→						textContentSource: textContent,
   342→						container: textLayerDiv,
   343→						viewport: viewport
   344→					});
   345→					await textLayer.render();
   346→					pageWrapper.appendChild(textLayerDiv);
   347→
   348→					container.appendChild(pageWrapper);
   349→				}
   350→			};
   351→			fileReader.readAsArrayBuffer(pdfFile);
   352→		}
   353→	}
   354→</script>
   355→
   356→<header class="nav-header">
   357→	<h1>PDF Splitter</h1>
   358→	<nav>
   359→		{#if pdfUrl}
   360→			<button
   361→				onclick={openSearch}
   362→				class="search-icon-btn"
   363→				title="Search in document (Cmd+F)"
   364→				aria-label="Search in document"
   365→			>
   366→				<svg
   367→					width="18"
   368→					height="18"
   369→					viewBox="0 0 24 24"
   370→					fill="none"
   371→					stroke="currentColor"
   372→					stroke-width="2"
   373→					stroke-linecap="round"
   374→					stroke-linejoin="round"
   375→				>
   376→					<circle cx="11" cy="11" r="8" />
   377→					<path d="M21 21l-4.35-4.35" />
   378→				</svg>
   379→			</button>
   380→		{/if}
   381→		{#if data.user}
   382→			<a href="/dashboard">Dashboard</a>
   383→		{:else}
   384→			<a href="/setup">Login / Sign Up</a>
   385→		{/if}
   386→	</nav>
   387→</header>
   388→
   389→<div class="content">
   390→	{#if pdfUrl && showSearchPopup}
   391→		<div class="search-popup">
   392→			<div class="search-input-wrapper">
   393→				<input
   394→					type="text"
   395→					placeholder="Find in document"
   396→					bind:value={searchQuery}
   397→					bind:this={searchInputEl}
   398→					oninput={performSearch}
   399→					onkeydown={handleSearchKeydown}
   400→					class="search-input"
   401→				/>
   402→				<span class="match-count">
   403→					{#if matchCount > 0}
   404→						{currentMatchIndex + 1} of {matchCount}
   405→					{:else if searchQuery.trim()}
   406→						No results
   407→					{/if}
   408→				</span>
   409→			</div>
   410→			<div class="search-controls">
   411→				<button
   412→					onclick={toggleMatchCase}
   413→					class="toggle-btn"
   414→					class:active={matchCase}
   415→					title="Match Case (Cmd+Opt+C)"
   416→					aria-label="Match case"
   417→					aria-pressed={matchCase}
   418→				>
   419→					Aa
   420→				</button>
   421→				<button
   422→					onclick={toggleMatchWholeWord}
   423→					class="toggle-btn"
   424→					class:active={matchWholeWord}
   425→					title="Match Whole Word (Cmd+Opt+W)"
   426→					aria-label="Match whole word"
   427→					aria-pressed={matchWholeWord}
   428→				>
   429→					<span class="whole-word-icon">W</span>
   430→				</button>
   431→				<div class="nav-buttons">
   432→					<button
   433→						onclick={prevMatch}
   434→						class="nav-btn"
   435→						title="Previous (Cmd+Shift+G)"
   436→						aria-label="Previous match"
   437→						disabled={matchCount === 0}
   438→					>
   439→						<svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor">
   440→							<path d="M6 3L1 8h10L6 3z" />
   441→						</svg>
   442→					</button>
   443→					<button
   444→						onclick={nextMatch}
   445→						class="nav-btn"
   446→						title="Next (Cmd+G)"
   447→						aria-label="Next match"
   448→						disabled={matchCount === 0}
   449→					>
   450→						<svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor">
   451→							<path d="M6 9L1 4h10L6 9z" />
   452→						</svg>
   453→					</button>
   454→				</div>
   455→				<button
   456→					onclick={closeSearch}
   457→					class="close-btn"
   458→					title="Close (Escape)"
   459→					aria-label="Close search"
   460→				>
   461→					<svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor">
   462→						<path
   463→							d="M9.5 3.2L8.8 2.5 6 5.3 3.2 2.5 2.5 3.2 5.3 6 2.5 8.8l.7.7L6 6.7l2.8 2.8.7-.7L6.7 6z"
   464→						/>
   465→					</svg>
   466→				</button>
   467→			</div>
   468→		</div>
   469→	{/if}
   470→
   471→	<h2>PDF Viewer</h2>
   472→
   473→	<input type="file" accept="application/pdf" onchange={handleFileChange} />
   474→	{#if pdfUrl}
   475→		<a href={pdfUrl} download={pdfFile?.name || 'download.pdf'} class="download-btn">Download PDF</a
   476→		>
   477→	{/if}
   478→	<div id="pdf-container" class="pdf"></div>
   479→</div>
