   571→	/* Page wrapper for canvas + text layer */
   572→	:global(.page-wrapper) {
   573→		position: relative;
   574→		box-shadow: 0 0 16px rgba(0, 0, 0, 0.15);
   575→	}
   576→
   577→	/* Search popup styles (browser-like) */
   578→	.search-popup {
   579→		position: fixed;
   580→		top: 80px;
   581→		right: 24px;
   582→		z-index: 1000;
   583→		display: flex;
   584→		align-items: center;
   585→		gap: 6px;
   586→		padding: 6px 8px;
   587→		background: #fff;
   588→		border-radius: 8px;
   589→		box-shadow:
   590→			0 2px 8px rgba(0, 0, 0, 0.15),
   591→			0 0 1px rgba(0, 0, 0, 0.1);
   592→		border: 1px solid #d1d5db;
   593→		font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
   594→	}
   595→
   596→	.search-input-wrapper {
   597→		display: flex;
   598→		align-items: center;
   599→		background: #f3f4f6;
