function performSearch() {
	// Clear previous highlights
	document.querySelectorAll('.search-highlight-overlay').forEach((el) => el.remove());
	highlightElements = [];
	matchCount = 0;
	currentMatchIndex = 0;

	if (!searchQuery.trim() || pagesData.length === 0) return;

	const query = matchCase ? searchQuery : searchQuery.toLowerCase();

	// Search through each page using the rendered text layer for accurate positioning
	pagesData.forEach((pageData) => {
		const textLayer = pageData.pageWrapper.querySelector('.textLayer');
		if (!textLayer) return;

		// Get all text spans in the text layer
		const spans = textLayer.querySelectorAll('span');

		// Build combined text with span/offset mapping
		interface CharInfo {
			span: HTMLSpanElement;
			textNode: Text;
			offsetInNode: number;
		}
		const charMap: CharInfo[] = [];
		let combinedText = '';

		spans.forEach((span) => {
			const textNode = span.firstChild;
			if (textNode && textNode.nodeType === Node.TEXT_NODE) {
				const text = textNode.textContent || '';
				for (let i = 0; i < text.length; i++) {
					charMap.push({ span, textNode: textNode as Text, offsetInNode: i });
				}
				combinedText += text;
			}
		});

		// Find matches
		const textToSearch = matchCase ? combinedText : combinedText.toLowerCase();
		let searchPos = 0;

		while (true) {
			const matchIndex = textToSearch.indexOf(query, searchPos);
			if (matchIndex === -1) break;

			// Check whole word boundary if enabled
			if (matchWholeWord) {
				const charBefore = matchIndex > 0 ? textToSearch[matchIndex - 1] : ' ';
				const charAfter =
					matchIndex + query.length < textToSearch.length
						? textToSearch[matchIndex + query.length]
						: ' ';
				const isWordBoundaryBefore = !/\w/.test(charBefore);
				const isWordBoundaryAfter = !/\w/.test(charAfter);

				if (!isWordBoundaryBefore || !isWordBoundaryAfter) {
					searchPos = matchIndex + 1;
					continue;
				}
			}

			const matchEnd = matchIndex + query.length;
			matchCount++;

			// Get start and end character info
			const startCharInfo = charMap[matchIndex];
			const endCharInfo = charMap[matchEnd - 1];

			if (!startCharInfo || !endCharInfo) {
				searchPos = matchIndex + 1;
				continue;
			}

			// Use Range API to get exact bounding rectangles
			const range = document.createRange();
			range.setStart(startCharInfo.textNode, startCharInfo.offsetInNode);
			range.setEnd(endCharInfo.textNode, endCharInfo.offsetInNode + 1);

			// Get all client rects (handles multi-line/multi-span matches)
			const rects = range.getClientRects();
			const wrapperRect = pageData.pageWrapper.getBoundingClientRect();

			for (const rect of rects) {
				const highlight = document.createElement('div');
				highlight.className = 'search-highlight-overlay';
				highlight.dataset.matchIndex = String(matchCount - 1);

				// Position relative to page wrapper
				highlight.style.left = `${rect.left - wrapperRect.left}px`;
				highlight.style.top = `${rect.top - wrapperRect.top}px`;
				highlight.style.width = `${rect.width}px`;
				highlight.style.height = `${rect.height}px`;

				pageData.pageWrapper.appendChild(highlight);
				highlightElements.push(highlight);
			}

			searchPos = matchIndex + 1;
		}
	});

	if (highlightElements.length > 0) {
		scrollToMatch(0);
	}
}

